function hashNumber(value) { return [...value].reduce((n, char) => ((n << 5) - n + char.charCodeAt(0)) | 0, 0) >>> 0; }
function choice(list, seed) { return list[seed % list.length]; }
function createGame(title, index, category) {
  const seed = hashNumber(`${title}-${index}`), developer = choice(developers, seed), sale = seed % 6 === 0 ? choice(["-20%", "-40%", "-90%"], seed >> 3) : "";
  const basePrices = ["$2.00", "$4.50", "$5.95", "$9.90", "$14.50", "$7.70", "$11.50"];
  return { id: `fake-${category}-${index}`, title, developer, publisher: choice(publishers, seed >> 4), tags: [choice(allTags, seed), choice(allTags, seed >> 8), choice(allTags, seed >> 13)].filter((v, i, a) => a.indexOf(v) === i), price: seed % 19 === 0 ? "Free to Play" : seed % 23 === 0 ? "Coming Soon" : choice(basePrices, seed >> 9), sale, reviewSummary: choice(["Very Positive", "Mostly Positive", "Mixed", "Positive"], seed >> 6), reviewCount: 31 + (seed % 5822), releaseDate: `${1 + (seed % 27)} ${choice(["Jan", "Mar", "May", "Jul", "Sep", "Nov"], seed >> 5)}, 2026`, description: choice(["A focused simulation about locating a very small object in a generously sized rural environment.", "Use practical tools, patience, and questionable intuition to solve the field’s smallest mystery.", "An authentic search experience with procedural straw placement and unusually specific objectives.", "A quiet, methodical game about agriculture, metal, and the spaces between them."], seed >> 10), isRealGame: false, coverStyle: choice(coverStyles, seed >> 2), dlc: seed % 4 === 0 ? choice(dlcNames, seed >> 3) : null };
}
const fakeGames = [...convincingTitles.map((title, i) => createGame(title, i, "convincing")), ...plausibleTitles.map((title, i) => createGame(title, i, "plausible")), ...absurdTitles.map((title, i) => createGame(title, i, "absurd"))];
realGame.coverStyle = choice(coverStyles, hashNumber(realGame.id));
const GAME_DATABASE = [...fakeGames, realGame];

// STATE — one tab’s run is stored to make accidental refreshes less cruel.
const defaultRun = () => ({ started: false, startTime: null, endTime: null, attempts: 0, gamesOpened: 0, uniqueGames: [], searches: 0, hints: 0, finished: false, widgetMinimized: false, catalogOrder: [] });
let run = defaultRun();
try { sessionStorage.removeItem("smoke-run"); } catch { /* Storage is optional for the static site. */ }
let catalog = orderedCatalog();
const SIDE_STORAGE_KEY = "smoke-sidequest-v1";
const freshLabsState = () => ({ day: "", earnedToday: 0, wheelSpins: 0, calibration: { best: 0, plays: 0 }, haysweeper: { bestTime: null, wins: 0 }, wheel: { jackpots: 0, spins: 0 }, tweezers: { best: 0, plays: 0 }, inventory: { bestMoves: null, wins: 0 }, conveyor: { best: 0, plays: 0 }, badges: [] });
const defaultSideState = () => ({ points: 0, unlocked: [], equipped: "Plain Smoke", wishlist: [], followed: [], ignored: [], language: "Agricultural English", forumVotes: [], newsRead: [], labBest: 0, labRewards: 0, humanVerified: false, installerReports: 0, labs: freshLabsState() });
let side = loadSideState();
let logoClicks = 0, konami = [], activeGameId = null, modalCleanup = null;
const app = document.querySelector("#app"), modalRoot = document.querySelector("#modalRoot"), widget = document.querySelector("#challengeWidget");

// UTILITY FUNCTIONS
function escapeHtml(value) { return String(value).replace(/[&<>'"]/g, char => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", "'": "&#39;", '"': "&quot;" })[char]); }
function shuffle(items) { const copy = [...items]; for (let i = copy.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [copy[i], copy[j]] = [copy[j], copy[i]]; } return copy; }
function getGame(id) { return GAME_DATABASE.find(game => game.id === id); }
function loadRun() { try { return { ...defaultRun(), ...JSON.parse(sessionStorage.getItem("smoke-run")) }; } catch { return defaultRun(); } }
function saveRun() { sessionStorage.setItem("smoke-run", JSON.stringify(run)); }
function loadSideState() { try { const saved = JSON.parse(localStorage.getItem(SIDE_STORAGE_KEY)) || {}; const base = defaultSideState(); const merged = { ...base, ...saved, labs: { ...base.labs, ...(saved.labs || {}) } }; for (const key of ["calibration", "haysweeper", "wheel", "tweezers", "inventory", "conveyor"]) merged.labs[key] = { ...base.labs[key], ...(saved.labs?.[key] || {}) }; merged.labs.calibration.best = Math.max(merged.labs.calibration.best, saved.labBest || 0); return merged; } catch { return defaultSideState(); } }
function saveSideState() { localStorage.setItem(SIDE_STORAGE_KEY, JSON.stringify(side)); }
function orderedCatalog() { const valid = run.catalogOrder.length === GAME_DATABASE.length && new Set(run.catalogOrder).size === GAME_DATABASE.length; if (!valid) { run.catalogOrder = shuffle(GAME_DATABASE.map(game => game.id)); saveRun(); } return run.catalogOrder.map(getGame); }
function formatTime(seconds) { const safe = Math.max(0, Math.floor(seconds)); return `${String(Math.floor(safe / 60)).padStart(2, "0")}:${String(safe % 60).padStart(2, "0")}`; }
function elapsed() { return run.startTime ? ((run.endTime || Date.now()) - run.startTime) / 1000 : 0; }
function showToast(message, type = "") { const toast = document.createElement("div"); toast.className = `toast ${type}`; toast.textContent = message; document.querySelector("#toastRegion").append(toast); setTimeout(() => toast.remove(), 3600); }
function engage() { if (!run.started && !run.finished) { run.started = true; run.startTime = Date.now(); saveRun(); renderWidget(); } }
function coverMarkup(game, className = "") { const seed = hashNumber(game.id); const style = game.coverStyle || choice(coverStyles, seed); const photo = encodeURI(choice(USER_COVER_PHOTOS, seed)); const badge = game.title.match(/Remastered|Prologue|Classic|2026|Ultimate|Dating|Kart|Definitive|Origins/i); return `<div class="cover-art photo-cover art-${style} ${className}" style="--cover-photo:url('${photo}')" aria-label="Haystack cover artwork for ${escapeHtml(game.title)}"><span class="cover-title">${escapeHtml(game.title)}</span>${badge ? `<span class="badge">${escapeHtml(badge[0].toUpperCase())}</span>` : ""}</div>`; }
function screenshotMarkup(variant = "") { return `<div class="screenshot ${variant}" aria-label="Procedural in-game screenshot"></div>`; }
function priceMarkup(game) { return `<div class="card-price">${game.sale ? `<span class="discount">${game.sale}</span>` : ""}<span>${escapeHtml(game.price)}</span></div>`; }
function selectFeature(seed = 0) { return catalog[(seed * 17 + 5) % catalog.length]; }

// ROUTER
function go(hash) { location.hash = hash; }
function route() { const raw = location.hash.slice(1) || "store"; if (raw.startsWith("game/")) renderGame(raw.slice(5)); else if (raw.startsWith("search")) renderSearch(new URLSearchParams(raw.split("?")[1] || "").get("q") || ""); else renderStore(); }
window.addEventListener("hashchange", route);

// STORE RENDERING
function gameCard(game) { return `<article class="game-card" data-game-id="${game.id}" tabindex="0" role="link" aria-label="View ${escapeHtml(game.title)}">${coverMarkup(game)}<div class="card-info"><div class="card-title">${escapeHtml(game.title)}</div><div class="card-tags">${escapeHtml(game.tags.slice(0, 2).join(", "))}</div>${priceMarkup(game)}</div></article>`; }
function renderRail(title, games) { return `<section class="section"><h2 class="section-heading">${escapeHtml(title)}</h2><div class="game-rail">${games.map(gameCard).join("")}</div></section>`; }
function railGames(offset) { const visibleCatalog = catalog.filter(game => game.isRealGame || !side.ignored.includes(game.id)); const source = visibleCatalog.length ? visibleCatalog : catalog; return Array.from({ length: 4 }, (_, i) => source[(offset + i * 11) % source.length]); }
function renderStore() {
  activeGameId = null; const feature = selectFeature(1);
  app.innerHTML = `<div class="page"><section class="hero-challenge" id="challengeBanner"><div><div class="eyebrow">FIND THE ORIGINAL</div><h1>Somewhere in the Smoke Store is the real <i>Needle in a Haystack Simulator.</i></h1><p>Everything else is suspicious.</p></div><button class="primary" id="startSearch">START SEARCHING</button></section><div class="store-layout"><aside class="sidebar"><h3>RECOMMENDED</h3><a href="#store">By friends</a><a href="#store">By curators</a><a href="#store">Tags</a><h3 style="margin-top:17px">BROWSE</h3><a href="#search?q=needle">Needles</a><a href="#search?q=haystack">Haystacks</a><a href="#search?q=simulator">Simulators</a><a href="#search?q=original">Original games</a><div class="side-note">SMOKE DISCOVERY QUEUE<br><br>1 genuine game.<br>A suspicious number of alternatives.</div></aside><div><section class="section"><h2 class="section-heading">FEATURED &amp; RECOMMENDED</h2><div class="featured" data-game-id="${feature.id}" role="link" tabindex="0">${coverMarkup(feature, "feature-art")}<div class="feature-info"><h2>${escapeHtml(feature.title)}</h2><div class="thumb-row">${screenshotMarkup()}${screenshotMarkup("alt")}${screenshotMarkup("ui")}</div><div class="small-meta">${escapeHtml(feature.releaseDate)}</div><div class="small-meta">${escapeHtml(feature.reviewSummary)} <span class="rating">(${feature.reviewCount.toLocaleString()})</span></div><div class="small-meta">${escapeHtml(feature.tags.join(", "))}</div><div class="price-row">${feature.sale ? `<span class="discount">${feature.sale}</span>` : ""}<span class="price">${escapeHtml(feature.price)}</span></div></div></div></section>${renderRail("TRENDING IN HAYSTACKS", railGames(7))}${renderRail("BECAUSE YOU PLAYED ‘LOOKING AT THINGS’", railGames(19))}${renderRail("NEEDLE FEST", railGames(31))}${renderRail("SPECIAL OFFERS", railGames(43))}${renderRail("POPULAR UPCOMING", railGames(55))}${renderRail("UNDER $10", railGames(67))}${renderRail("MORE LIKE NEEDLE IN A HAYSTACK SIMULATOR", railGames(13))}${renderRail("THE HAYSTACK COLLECTION", railGames(37))}</div></div></div>`;
  bindGameLinks(); document.querySelector("#startSearch").addEventListener("click", () => { engage(); document.querySelector("#challengeBanner").classList.add("hidden"); showToast("Search initiated. Please inspect responsibly."); });
  renderWidget();
}
function bindGameLinks() { document.querySelectorAll("[data-game-id]").forEach(element => { const open = event => { if (event?.target.closest(".screenshot")) return; engage(); go(`#game/${element.dataset.gameId}`); }; element.addEventListener("click", open); element.addEventListener("keydown", e => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); open(e); } }); }); }

// SEARCH
function renderSearch(query) {
  engage(); const normalized = query.trim().toLowerCase(); let note = "", results;
  if (normalized === "where is the real one") { note = "Nice try."; results = catalog.slice(0, 18); }
  else if (normalized === "steam") { note = "Did you mean: Smoke?"; results = catalog.filter(game => /needle|haystack/i.test(game.title)).slice(0, 28); }
  else if (normalized === "gabe") { note = "No relevant needles found."; results = []; }
  else if (normalized === "half-life 3") { note = "0 results."; results = []; }
  else if (normalized === "*") { note = "Yes, technically all of this is data."; results = catalog; }
  else { results = catalog.filter(game => `${game.title} ${game.developer} ${game.tags.join(" ")}`.toLowerCase().includes(normalized)); if (normalized === "real" || normalized === "original") note = "Smoke Search does not provide philosophical guarantees."; }
  app.innerHTML = `<div class="page"><div class="search-head"><h1>Search results for “${escapeHtml(query)}”</h1><p>${note || `${results.length} completely useful results`}</p></div><div class="store-layout"><aside class="sidebar"><h3>NARROW BY TAG</h3>${allTags.slice(0, 10).map(tag => `<a href="#search?q=${encodeURIComponent(tag)}">${tag}</a>`).join("")}</aside><section>${results.length ? results.map(game => `<article class="listing" data-game-id="${game.id}" tabindex="0" role="link">${coverMarkup(game)}<div class="listing-info"><div class="listing-title">${escapeHtml(game.title)}</div><div class="listing-meta">${escapeHtml(game.tags.join(", "))}<br>${escapeHtml(game.reviewSummary)} (${game.reviewCount.toLocaleString()})</div></div><div class="listing-price">${game.sale ? `<span class="discount">${game.sale}</span> ` : ""}${escapeHtml(game.price)}</div></article>`).join("") : `<div class="empty">There is nothing here. This is not evidence of anything.</div>`}</section></div></div>`;
  bindGameLinks(); renderWidget();
}
function submitSearch(event) { event.preventDefault(); const value = document.querySelector("#searchInput").value.trim(); if (!value) { showToast("Smoke Search requires at least one suspicious word."); return; } engage(); run.searches++; saveRun(); go(`#search?q=${encodeURIComponent(value)}`); }

// GAME PAGE
function renderGame(id) {
  const game = getGame(id); if (!game) { go("#store"); return; } activeGameId = id; window.scrollTo({ top: 0, left: 0, behavior: "auto" }); engage(); run.gamesOpened++; if (!run.uniqueGames.includes(id)) run.uniqueGames.push(id); saveRun();
  const seed = hashNumber(id); const reviews = Array.from({ length: 3 }, (_, i) => ({ user: choice(userNames, seed + i * 17), time: `${((seed >> (i + 1)) % 142 + 4) / 10} hrs`, text: choice(reviewSnippets, seed + i * 31) }));
  const gameAchievements = achievements.slice(0, 3 + (seed % 3));
  app.innerHTML = `<div class="page"><div class="breadcrumb"><a href="#store">All Games</a> &gt; ${escapeHtml(game.tags[0])} &gt; ${escapeHtml(game.title)}</div><article class="game-page"><h1 class="game-title">${escapeHtml(game.title)}</h1><div class="product-top"><div>${coverMarkup(game, "game-hero")}<div class="gallery">${screenshotMarkup()}${screenshotMarkup("alt")}${screenshotMarkup("ui")}${screenshotMarkup("alt")}</div></div><aside class="product-side">${coverMarkup(game)}<p>${escapeHtml(game.description)}</p><div class="detail-line"><strong>ALL REVIEWS</strong><span class="rating">${escapeHtml(game.reviewSummary)}</span> (${game.reviewCount.toLocaleString()})</div><div class="detail-line"><strong>RELEASE DATE</strong>${escapeHtml(game.releaseDate)}</div><div class="detail-line"><strong>DEVELOPER</strong><span class="rating">${escapeHtml(game.developer)}</span></div><div class="detail-line"><strong>PUBLISHER</strong><span class="rating">${escapeHtml(game.publisher)}</span></div><div class="tags">${game.tags.map(tag => `<span class="tag">${escapeHtml(tag)}</span>`).join("")}</div><div class="action-row"><button class="secondary wishlist" data-id="${game.id}">Add to your Smoke Wishlist</button><button class="secondary">Follow</button><button class="secondary">Ignore</button></div></aside></div><div class="content-columns"><div><section class="product-section"><h3>ABOUT THIS GAME</h3><p>${escapeHtml(game.description)} Players are encouraged to observe closely, question every straw, and trust no similarly named product.</p><p class="small-meta">“A grounded search simulator with a remarkable amount of hay.”</p></section><section class="product-section"><h3>USER REVIEWS</h3>${reviews.map(review => `<div class="review"><b>${escapeHtml(review.user)}</b><span>${review.time}</span><p>${escapeHtml(review.text)}</p></div>`).join("")}</section>${game.dlc ? `<section class="product-section"><h3>CONTENT FOR THIS GAME</h3><div class="listing"><div class="listing-info"><div class="listing-title">${escapeHtml(game.title)} — ${escapeHtml(game.dlc)}</div><div class="listing-meta">Additional extremely necessary content</div></div><div class="listing-price">$${(seed % 7 + 1)}.95</div></div></section>` : ""}</div><aside><section class="product-section"><h3>ACHIEVEMENTS</h3>${gameAchievements.map((achievement, i) => `<div class="achievement"><span class="achievement-icon">${i === 2 ? "⌖" : "✦"}</span><div><b>${achievement[0]}</b><small>${achievement[1]}</small></div></div>`).join("")}</section><section class="product-section"><h3>PLAYER STATISTICS</h3><div class="small-meta">${(seed % 9000 + 120).toLocaleString()} searching now</div><div class="small-meta">${(seed % 300000 + 4000).toLocaleString()} peak today</div></section></aside></div><section class="purchase"><div><h3>Get ${escapeHtml(game.title)}</h3><small>${game.isRealGame ? "The original is finally within reach." : "This looks extremely promising."}</small></div><div>${game.sale ? `<span class="discount">${game.sale}</span>` : ""} <span class="price">${escapeHtml(game.price)}</span> <button class="primary guess-button" data-id="${game.id}">THIS IS THE ONE</button></div></section></article></div>`;
  const purchasePanel = app.querySelector(".purchase"); app.querySelector(".product-side").prepend(purchasePanel); purchasePanel.classList.add("top-purchase"); window.scrollTo({ top: 0, left: 0, behavior: "auto" }); app.focus({ preventScroll: true }); document.querySelector(".guess-button").addEventListener("click", () => guess(game.id)); const wishlistButton = document.querySelector(".wishlist"); wishlistButton.textContent = side.wishlist.includes(game.id) ? "On Smoke Wishlist" : "Add to your Smoke Wishlist"; wishlistButton.classList.toggle("active", side.wishlist.includes(game.id)); wishlistButton.addEventListener("click", event => toggleWishlist(game.id, event.currentTarget)); const [followButton, ignoreButton] = [...document.querySelectorAll(".action-row .secondary:not(.wishlist)")]; followButton.textContent = side.followed.includes(game.id) ? "Following" : "Follow"; followButton.classList.toggle("active", side.followed.includes(game.id)); ignoreButton.textContent = side.ignored.includes(game.id) ? "Ignored" : "Ignore"; ignoreButton.classList.toggle("active", side.ignored.includes(game.id)); renderWidget();
}

// CHALLENGE LOGIC
function guess(id) { const game = getGame(id); openModal(`<h2>Are you sure?</h2><p>Are you sure this is the original <b>Needle in a Haystack Simulator</b>?</p><div class="modal-actions"><button class="primary" id="confirmGuess">Yes, definitely</button><button class="secondary" id="cancelGuess">Back to searching</button></div>`); document.querySelector("#confirmGuess").addEventListener("click", () => { closeModal(); if (game.isRealGame) win(); else wrongGuess(game); }); document.querySelector("#cancelGuess").addEventListener("click", closeModal); }
function wrongGuess(game) { run.attempts++; saveRun(); showToast(choice(wrongMessages, Math.floor(Math.random() * wrongMessages.length)), "error"); if (CONFIG.enableHints && run.attempts === 3) showToast("Smoke Discovery Queue has detected uncertainty."); if (CONFIG.enableHints && run.attempts >= 5) setTimeout(showHintPrompt, 500); renderWidget(); }
function showHintPrompt() { openModal(`<h2>Smoke Discovery Queue</h2><p>We have detected a sustained period of extremely legitimate uncertainty.</p><div class="modal-actions"><button class="primary" id="hintButton">Request vague hint</button><button class="secondary" id="noHint">I remain confident</button></div>`); document.querySelector("#hintButton").onclick = () => { run.hints++; saveRun(); const hint = run.attempts >= 10 ? "Look for the listing that exactly states the task, without an addendum, sequence number, or marketing recovery plan." : choice(hints, run.hints + run.attempts); closeModal(); showToast(`VAGUE HINT: ${hint}`); renderWidget(); }; document.querySelector("#noHint").onclick = closeModal; }
function rank() { const score = run.attempts * 3 + run.hints * 4 + elapsed() / 45; return score < 3 ? "Chief Needle Officer" : score < 8 ? "Haystack Forensics Specialist" : score < 15 ? "Senior Needle Analyst" : score < 25 ? "Certified Haystack Technician" : "Needle Enjoyer"; }
function win() { run.endTime = Date.now(); run.finished = true; saveRun(); showToast("ACHIEVEMENT UNLOCKED — Needleception", "achievement"); const fakeOpened = run.uniqueGames.filter(id => !getGame(id).isRealGame).length; const coverage = Math.round((run.uniqueGames.length / GAME_DATABASE.length) * 100); const stats = [["TIME", formatTime(elapsed())], ["GAMES INSPECTED", run.uniqueGames.length], ["FAKE GAMES OPENED", fakeOpened], ["WRONG NEEDLES", run.attempts], ["SEARCHES", run.searches], ["STOREFRONT COVERED", `${coverage}%`], ["HINTS USED", run.hints], ["TITLE", rank()]]; openModal(`<div class="victory-inner"><div class="eyebrow">ACHIEVEMENT UNLOCKED · NEEDLECEPTION</div><h2>YOU FOUND IT</h2><div class="win-game">NEEDLE IN A HAYSTACK SIMULATOR</div><p>You successfully found Needle in a Haystack Simulator inside the Find Needle in a Haystack Simulator Simulator.</p><div class="stat-grid">${stats.map(stat => `<div class="stat"><b class="${stat[0] === "TITLE" ? "rank" : ""}">${escapeHtml(stat[1])}</b><span>${stat[0]}</span></div>`).join("")}</div><div class="modal-actions"><button class="primary" id="viewReal">View the real game</button><button class="secondary" id="shareResult">Share Result</button><button class="secondary" id="replay">Play Again</button></div></div>`, "victory"); document.querySelector("#viewReal").onclick = () => { if (REAL_GAME_URL.includes("PUT_REAL")) showToast("Set REAL_GAME_URL in script.js before publishing."); else window.open(REAL_GAME_URL, "_blank", "noopener"); }; document.querySelector("#shareResult").onclick = shareResult; document.querySelector("#replay").onclick = replay; renderWidget(); }

// STATS AND MODALS
function renderWidget() { if (!run.started || run.finished) { widget.classList.add("hidden"); return; } widget.classList.remove("hidden"); widget.classList.toggle("minimized", run.widgetMinimized); widget.innerHTML = run.widgetMinimized ? `<button aria-label="Expand challenge status">⌃ ORIGINAL GAME SEARCH</button>` : `<div class="widget-top"><span>ORIGINAL GAME SEARCH</span><button aria-label="Minimize challenge status">—</button></div><div class="widget-stats">Attempts <b>${run.attempts}</b><br>Games inspected <b>${run.uniqueGames.length}</b><br>Time <b id="widgetTime">${formatTime(elapsed())}</b></div>`; widget.querySelector("button").onclick = () => { run.widgetMinimized = !run.widgetMinimized; saveRun(); renderWidget(); }; }
function updateTimer() { if (run.started && !run.finished) { const timer = document.querySelector("#widgetTime"); if (timer) timer.textContent = formatTime(elapsed()); } }
function openModal(content, className = "") { if (modalCleanup) { modalCleanup(); modalCleanup = null; } document.body.classList.add("modal-open"); modalRoot.innerHTML = `<div class="modal-backdrop" role="dialog" aria-modal="true"><div class="modal ${className}">${content}</div></div>`; modalRoot.querySelector(".modal-backdrop").addEventListener("click", event => { if (event.target === event.currentTarget) closeModal(); }); const first = modalRoot.querySelector("button"); if (first) first.focus(); }
function closeModal() { if (modalCleanup) { modalCleanup(); modalCleanup = null; } delete modalRoot.dataset.labActive; document.body.classList.remove("modal-open"); modalRoot.innerHTML = ""; }
function shareText() { return `I found the real Needle in a Haystack Simulator among ${GAME_DATABASE.length - 1} extremely legitimate games on Smoke.\n\n⏱ ${formatTime(elapsed())}\n${run.uniqueGames.length} games inspected\n❌ ${run.attempts} wrong needles\n\nCan you find it faster?\n${location.href.split("#")[0]}`; }
async function shareResult() { const text = shareText(); try { await navigator.clipboard.writeText(text); showToast("Result copied to clipboard."); } catch { const area = document.createElement("textarea"); area.value = text; document.body.append(area); area.select(); try { document.execCommand("copy"); showToast("Result copied to clipboard."); } catch { showToast("Copy unavailable — your result is ready in the page source."); } area.remove(); } }
function replay() { closeModal(); run = defaultRun(); sessionStorage.removeItem("smoke-run"); catalog = orderedCatalog(); go("#store"); showToast("The haystack has been responsibly reshuffled."); }

// EASTER EGGS
function installSmoke() { showToast("Installing Smoke…"); const toast = document.createElement("div"); toast.className = "toast"; toast.innerHTML = `Installing Smoke <div class="install-progress"><i></i></div>`; document.querySelector("#toastRegion").append(toast); setTimeout(() => { toast.textContent = "Smoke installation failed successfully."; toast.classList.add("error"); }, 2400); setTimeout(() => openInstallerReport(), 2800); setTimeout(() => toast.remove(), 5800); }
function setupEasterEggs() { document.querySelector("#brandButton").addEventListener("click", () => { logoClicks++; if (logoClicks === 7) { openSmokeStatus(); logoClicks = 0; } go("#store"); }); document.querySelector("#installButton").addEventListener("click", installSmoke); document.addEventListener("keydown", event => { if (!CONFIG.enableEasterEggs) return; konami.push(event.key.toLowerCase()); konami = konami.slice(-10); const code = ["arrowup", "arrowup", "arrowdown", "arrowdown", "arrowleft", "arrowright", "arrowleft", "arrowright", "b", "a"]; if (konami.join(",") === code.join(",")) { document.querySelectorAll(".card-title,.listing-title,.cover-title").forEach(node => { node.dataset.old = node.textContent; node.textContent = "Needle in a Haystack Simulator"; }); showToast("Catalog normalization complete."); setTimeout(route, 3000); } }); document.addEventListener("keydown", event => { if (event.key === "Escape") { if (modalRoot.dataset.labActive) openLabs(); else closeModal(); } }); }

// INITIALIZATION
document.body.classList.add("ui-refresh");
applyLanguage();
document.querySelector("#searchForm").addEventListener("submit", submitSearch);
setupEasterEggs(); setupInteractionPolish(); route(); setInterval(updateTimer, 1000);

// Passive storefront controls are intentionally local, but never leave a dead button behind.
function setupInteractionPolish() {
  document.addEventListener("click", event => {
    const sideAction = event.target.closest("[data-side-action]");
    if (sideAction) { event.preventDefault(); handleSideAction(sideAction.dataset.sideAction); return; }
    const sidebarLink = event.target.closest(".sidebar a[href='#store']");
    if (sidebarLink) { event.preventDefault(); handleSidebarAction(sidebarLink.textContent.trim()); return; }
    const action = event.target.closest(".action-row .secondary:not(.wishlist)");
    if (action) handleProductAction(action);
    const screenshot = event.target.closest(".gallery .screenshot,.thumb-row .screenshot");
    if (screenshot) openScreenshotViewer(screenshot);
  });
}

// OPTIONAL SMOKE ARCADE — local-only diversions that never influence the main search.
const SHOP_ITEMS = [
  { name: "Plain Smoke", cost: 0, note: "The standard issue atmosphere." },
  { name: "Smouldering Bale", cost: 20, note: "Adds a warm glow to absolutely nothing." },
  { name: "Chrome Needle", cost: 45, note: "For players who enjoy reflective metadata." },
  { name: "Certified Hay", cost: 75, note: "Third-party hay verification pending." }
];

function awardPoints(amount, reason) { side.points += amount; saveSideState(); showToast(`+${amount} Smoke Points — ${reason}`, "achievement"); }
function toggleWishlist(gameId, button) { const saved = side.wishlist.includes(gameId); side.wishlist = saved ? side.wishlist.filter(id => id !== gameId) : [...side.wishlist, gameId]; saveSideState(); button.classList.toggle("active", !saved); button.textContent = saved ? "Add to your Smoke Wishlist" : "On Smoke Wishlist"; showToast(saved ? "Removed from your Smoke Wishlist." : "Added to your Smoke Wishlist."); }
function handleProductAction(button) {
  if (!activeGameId) return; const isFollow = button.textContent.trim().startsWith("Follow"); const collection = isFollow ? side.followed : side.ignored; const already = collection.includes(activeGameId);
  if (isFollow) { side.followed = already ? collection.filter(id => id !== activeGameId) : [...collection, activeGameId]; button.textContent = already ? "Follow" : "Following"; }
  else { side.ignored = already ? collection.filter(id => id !== activeGameId) : [...collection, activeGameId]; button.textContent = already ? "Ignore" : "Ignored"; }
  button.classList.toggle("active", !already); saveSideState(); showToast(isFollow ? (already ? "Follow signal withdrawn." : "You will be notified of future straw developments.") : (already ? "This listing has been restored to your peripheral vision." : "Ignored listings leave recommendation rails, not search results."));
}
function handleSideAction(action) {
  const handlers = { store: () => go("#store"), community: openCommunity, about: openAbout, support: openSupport, login: openLogin, language: openLanguage, new: openNewReleases, categories: openCategories, points: openPointsShop, news: openNews, labs: openLabs };
  (handlers[action] || (() => showToast("This button has entered a contemplative state.")))();
}
function handleSidebarAction(label) { if (label === "By friends") openFriends(); else if (label === "By curators") openCurators(); else if (label === "Tags") openCategories(); }
function openSide(title, content, className = "side-modal") { openModal(`<div class="side-heading"><span class="eyebrow">SMOKE OPTIONAL ACTIVITY</span><h2>${escapeHtml(title)}</h2></div>${content}`, className); }
function copyText(text, success) { navigator.clipboard?.writeText(text).then(() => showToast(success)).catch(() => showToast(text)); }

function openCommunity() {
  const threads = [["Hay physics: discussion", "The hay is behaving as intended."], ["Is ‘needle’ a tag or a lifestyle?", "Please stay on topic: hay."], ["Looking At Things appreciation post", "This review has been inspected 17 times."]];
  openSide("Haystack Forum", `<p class="side-intro">A small, quiet community where every topic eventually becomes hay.</p><div class="forum-list">${threads.map(([title, reply], i) => `<article class="forum-thread"><b>${title}</b><p>${reply}</p><button class="secondary forum-vote" data-thread="${i}">${side.forumVotes.includes(i) ? "Helpful ✓" : "Mark helpful"}</button></article>`).join("")}</div>`);
  modalRoot.querySelectorAll(".forum-vote").forEach(button => button.onclick = () => { const id = Number(button.dataset.thread); if (!side.forumVotes.includes(id)) { side.forumVotes.push(id); awardPoints(2, "responsible forum participation"); } saveSideState(); button.textContent = "Helpful ✓"; button.disabled = true; });
}
function openAbout() { openSide("About Smoke", `<p class="side-intro">Smoke is a completely legitimate digital game storefront with no relationship to any similarly arranged blue websites.</p><div class="status-meter"><span>INFRASTRUCTURE CONFIDENCE</span><i><b></b></i><small>93% operational · 7% atmospheric</small></div><div class="side-actions"><button class="secondary" id="aboutStatus">Run smoke test</button></div>`); document.querySelector("#aboutStatus").onclick = () => showToast("Smoke test passed. Visibility remains limited."); }
function openSmokeStatus() { openSide("Smoke Infrastructure", `<p class="side-intro">Please stop hitting the infrastructure. It is doing its best.</p><div class="status-meter"><span>HAYSTACK PRESSURE</span><i><b></b></i><small>Nominal, with localized straw turbulence.</small></div><div class="modal-actions"><button class="secondary" id="statusCopy">Copy incident number</button><button class="primary" id="statusClose">Understood</button></div>`); document.querySelector("#statusCopy").onclick = () => copyText(`SMOKE-${Date.now().toString(36).toUpperCase()}`, "Incident number copied. Nobody has been assigned."); document.querySelector("#statusClose").onclick = closeModal; }
function openInstallerReport() { side.installerReports++; saveSideState(); const report = `SMOKE-INSTALL-${String(side.installerReports).padStart(3, "0")}`; openSide("Smoke Installer Diagnostics", `<p class="side-intro">Installation stopped at 99% because the final percent became theoretical.</p><div class="status-meter"><span>INSTALLATION CONFIDENCE</span><i><b></b></i><small>Error ${report}: smoke detected in a smoke-adjacent location.</small></div><div class="modal-actions"><button class="secondary" id="installerCopy">Copy failure report</button><button class="primary" id="installerClose">Accept atmospheric conditions</button></div>`); document.querySelector("#installerCopy").onclick = () => copyText(report, "Failure report copied to clipboard."); document.querySelector("#installerClose").onclick = closeModal; }
function openSupport() {
  const ticket = `HAY-${Math.random().toString(36).slice(2, 8).toUpperCase()}`;
  openSide("Missing Needle Report", `<p class="side-intro">We take every missing needle seriously, especially the theoretical ones.</p><div class="report-options"><button class="secondary" data-report="barn">It was last seen near a barn</button><button class="secondary" data-report="field">The field is too field-like</button><button class="secondary" data-report="needle">I may have found a different needle</button></div><p id="ticketResult" class="hidden">Ticket <b>${ticket}</b> has been forwarded to the Department of Extremely Small Objects.</p>`);
  modalRoot.querySelectorAll("[data-report]").forEach(button => button.onclick = () => { document.querySelector("#ticketResult").classList.remove("hidden"); copyText(ticket, "Ticket ID copied. Assistance will arrive at hay speed."); });
}
function openLogin() {
  const correct = Math.floor(Math.random() * 3); const labels = ["Bale A", "Bale B", "Bale C"];
  openSide("Identity Reassurance", `<p class="side-intro">To continue, select the haystack that is most likely to understand you.</p><div class="identity-grid">${labels.map((label, i) => `<button class="identity-card" data-human="${i}">${coverMarkup({ id: `identity-${i}`, title: label, coverStyle: "hay" })}<span>${label}</span></button>`).join("")}</div><p id="identityResult"></p>`);
  modalRoot.querySelectorAll("[data-human]").forEach(button => button.onclick = () => { const answer = Number(button.dataset.human); const firstVerification = !side.humanVerified; side.humanVerified = true; saveSideState(); document.querySelector("#identityResult").textContent = answer === correct ? "Confirmed: reassuringly human." : "Unexpected choice. Still reassuringly human."; if (firstVerification) awardPoints(8, "passing a very relaxed identity check"); else showToast("Your humanity remains on file."); modalRoot.querySelectorAll("[data-human]").forEach(card => card.disabled = true); });
}
function openLanguage() {
  const options = ["Agricultural English", "Needle Morse", "International Hay"];
  openSide("Language Preferences", `<p class="side-intro">Translation is a living field.</p><div class="language-list">${options.map(option => `<button class="secondary ${side.language === option ? "active" : ""}" data-language="${option}">${option}</button>`).join("")}</div>`);
  modalRoot.querySelectorAll("[data-language]").forEach(button => button.onclick = () => { side.language = button.dataset.language; saveSideState(); applyLanguage(); closeModal(); showToast(`Language preference set to ${side.language}.`); });
}
function applyLanguage() { const button = document.querySelector("[data-side-action='language']"); if (button) button.textContent = side.language === "Agricultural English" ? "language ▾" : `${side.language.split(" ")[0].toLowerCase()} ▾`; }
function openNewReleases() { const games = catalog.slice(0, 5); openSide("New & Noteworthy", `<p class="side-intro">Released just moments before this panel was opened.</p>${games.map(game => `<button class="mini-game-link" data-open-game="${game.id}">${coverMarkup(game)}<span><b>${escapeHtml(game.title)}</b><small>Freshly released · ${escapeHtml(game.price)}</small></span></button>`).join("")}`); bindMiniGameLinks(); }
function openCategories() { openSide("Browse Categories", `<p class="side-intro">Browse by the most scientifically useful classifications available.</p><div class="category-grid">${allTags.map(tag => `<button class="tag" data-category="${escapeHtml(tag)}">${escapeHtml(tag)}</button>`).join("")}</div>`); modalRoot.querySelectorAll("[data-category]").forEach(button => button.onclick = () => { closeModal(); go(`#search?q=${encodeURIComponent(button.dataset.category)}`); }); }
function openPointsShop() {
  openSide("Smoke Points Shop", `<div class="points-balance"><b>${side.points}</b><span>SMOKE POINTS</span><small>Cosmetic only. The needle remains unimpressed.</small></div><div class="shop-grid">${SHOP_ITEMS.map(item => { const owned = side.unlocked.includes(item.name) || item.cost === 0; return `<article class="shop-item ${side.equipped === item.name ? "equipped" : ""}"><b>${item.name}</b><p>${item.note}</p><small>${item.cost ? `${item.cost} points` : "Included with smoke"}</small><button class="secondary" data-shop="${item.name}">${side.equipped === item.name ? "Equipped" : owned ? "Equip" : "Unlock"}</button></article>`; }).join("")}</div>`);
  modalRoot.querySelectorAll("[data-shop]").forEach(button => button.onclick = () => purchaseCosmetic(button.dataset.shop));
}
function purchaseCosmetic(name) { const item = SHOP_ITEMS.find(entry => entry.name === name); const owned = side.unlocked.includes(name) || item.cost === 0; if (!owned && side.points < item.cost) { showToast(`Need ${item.cost - side.points} more Smoke Points.`); return; } if (!owned) { side.points -= item.cost; side.unlocked.push(name); } side.equipped = name; saveSideState(); openPointsShop(); showToast(`${name} equipped. Visual impact: debatable.`); }
function openNews() {
  const stories = [["Patch 1.0.0.4", "Three additional pieces of hay were added after community feedback."], ["Service update", "The discovery queue now recognizes 14% more uncertainty."], ["Developer post", "We remain committed to small objects in large places."]];
  openSide("Smoke Dispatch", `<div class="news-list">${stories.map(([title, body], i) => `<article class="news-item ${side.newsRead.includes(i) ? "read" : ""}"><button data-news="${i}"><b>${title}</b><span>${side.newsRead.includes(i) ? "Read" : "Open"}</span></button><p class="hidden">${body}</p></article>`).join("")}</div>`);
  modalRoot.querySelectorAll("[data-news]").forEach(button => button.onclick = () => { const id = Number(button.dataset.news); if (!side.newsRead.includes(id)) side.newsRead.push(id); saveSideState(); button.parentElement.classList.add("read"); button.parentElement.querySelector("p").classList.remove("hidden"); button.querySelector("span").textContent = "Read"; });
}
function openFriends() { openSide("Friends Who Own Things", `<p class="side-intro">Your friends are all playing games with unsettlingly similar names.</p><div class="friend-list"><p><b>HayEnjoyer92</b><span>Currently searching a barn</span></p><p><b>MetalDetectorDad</b><span>12.4 hrs in Needle Finder 3D</span></p><p><b>StrawMan</b><span>Wishes you would stop ignoring games</span></p></div>`); }
function openCurators() { openSide("Curator Connectors", `<p class="side-intro">Independent voices for the discerning haystack consumer.</p><div class="friend-list"><p><b>Needle Adjacent</b><span>“This contains metal.”</span></p><p><b>The Barn Standard</b><span>“Appropriately rural.”</span></p><p><b>Object Not Found</b><span>“We could not locate a reason not to recommend it.”</span></p></div>`); }
function bindMiniGameLinks() { modalRoot.querySelectorAll("[data-open-game]").forEach(button => button.onclick = () => { closeModal(); go(`#game/${button.dataset.openGame}`); }); }
function openScreenshotViewer(clicked) {
  const labels = ["Search operation in progress", "Detector calibration at 03%", "An interface has asked a difficult question", "The hay remains uncooperative"]; let index = [...document.querySelectorAll(".gallery .screenshot,.thumb-row .screenshot")].indexOf(clicked); if (index < 0) index = 0;
  const draw = () => { openSide("Field Screenshot", `<div class="lightbox-shot">${screenshotMarkup(index % 3 === 1 ? "alt" : index % 3 === 2 ? "ui" : "")}</div><p class="side-intro">${labels[index % labels.length]}</p><div class="modal-actions"><button class="secondary" id="shotPrevious">Previous</button><button class="secondary" id="shotNext">Next</button><button class="primary" id="shotClose">Back to fieldwork</button></div>`); document.querySelector("#shotPrevious").onclick = () => { index = (index + labels.length - 1) % labels.length; draw(); }; document.querySelector("#shotNext").onclick = () => { index = (index + 1) % labels.length; draw(); }; document.querySelector("#shotClose").onclick = closeModal; };
  draw();
}
function openLabs() {
  let score = 0, target = Math.floor(Math.random() * 12), selected = 0, remaining = 20, interval;
  const draw = () => { openSide("Needle Calibration Lab", `<p class="side-intro">Calibrate the detector: locate the suspicious tile before the clock does.</p><div class="lab-score"><b id="labScore">${score}</b><span>CALIBRATIONS</span><b id="labTime">${remaining}s</b></div><div class="lab-grid">${Array.from({ length: 12 }, (_, i) => `<button class="lab-tile" data-tile="${i}" aria-label="Inspect hay tile ${i + 1}"><span>⌁</span></button>`).join("")}</div><p id="labMessage" class="side-intro">Use arrow keys or tap a tile. The detector is being normal.</p><button class="secondary" id="labExit">Leave laboratory</button>`); modalRoot.querySelector("#labExit").onclick = closeModal; modalRoot.querySelectorAll("[data-tile]").forEach(button => button.onclick = () => inspectTile(Number(button.dataset.tile))); modalRoot.querySelector(`[data-tile='${selected}']`)?.focus(); };
  const inspectTile = tile => { if (remaining <= 0) return; if (tile === target) { score++; target = Math.floor(Math.random() * 12); document.querySelector("#labMessage").textContent = "Signal acquired. This is statistically encouraging."; } else { remaining = Math.max(0, remaining - 2); document.querySelector("#labMessage").textContent = "Mostly hay. The detector looks disappointed."; } document.querySelector("#labScore").textContent = score; document.querySelector("#labTime").textContent = `${remaining}s`; };
  draw();
  const keyHandler = event => { if (!modalRoot.querySelector(".lab-grid")) return; const moves = { ArrowLeft: -1, ArrowRight: 1, ArrowUp: -4, ArrowDown: 4 }; if (event.key in moves) { event.preventDefault(); selected = Math.max(0, Math.min(11, selected + moves[event.key])); modalRoot.querySelector(`[data-tile='${selected}']`)?.focus(); } if (event.key === "Enter" || event.key === " ") { event.preventDefault(); inspectTile(selected); } };
  document.addEventListener("keydown", keyHandler); interval = setInterval(() => { remaining--; const time = document.querySelector("#labTime"); if (time) time.textContent = `${Math.max(0, remaining)}s`; if (remaining <= 0) { clearInterval(interval); const reward = Math.max(3, score * 3); side.labBest = Math.max(side.labBest, score); if (side.labRewards < 3) { side.labRewards++; awardPoints(reward, `Lab result: ${score} calibrations`); } else { saveSideState(); showToast("Lab reward allotment exhausted. Science continues regardless."); } document.querySelector("#labMessage").textContent = `Lab complete. Personal best: ${side.labBest}.`; modalRoot.querySelectorAll(".lab-tile").forEach(tile => tile.disabled = true); } }, 1000);
  modalCleanup = () => { clearInterval(interval); document.removeEventListener("keydown", keyHandler); };
}

// SMOKE LABORATORIES — arcade games are local, cosmetic, and isolated from the discovery challenge.
const LAB_GAMES = [
  { id: "calibration", title: "Needle Calibration", meta: "Reaction", text: "Find detector signals before the clock becomes theoretical." },
  { id: "haysweeper", title: "Haysweeper", meta: "Strategy", text: "Avoid mines, read the hay, and locate one extremely small object." },
  { id: "wheel", title: "Needle Wheel", meta: "Chance", text: "Spin a completely responsible wheel of hay for fictional points." },
  { id: "tweezers", title: "Precision Tweezers", meta: "Timing", text: "Close the tweezers when the needle agrees with you." },
  { id: "inventory", title: "Barn Inventory", meta: "Memory", text: "Match every suspicious object before the barn closes." },
  { id: "conveyor", title: "Conveyor Inspection", meta: "Reaction", text: "Send hay to storage and needles to evidence." }
];
function localDay() { return new Date().toLocaleDateString("en-CA"); }
function labDaily() { const labs = side.labs; if (labs.day !== localDay()) { labs.day = localDay(); labs.earnedToday = 0; labs.wheelSpins = 0; saveSideState(); } return labs; }
function awardLabPoints(amount, reason) { const labs = labDaily(); const granted = Math.max(0, Math.min(amount, 100 - labs.earnedToday)); labs.earnedToday += granted; side.points += granted; saveSideState(); if (granted) showToast(`+${granted} Smoke Points — ${reason}`, "achievement"); else showToast("Daily Lab reward cap reached. Practice data remains valid."); return granted; }
function unlockLabBadge(name) { if (!side.labs.badges.includes(name)) { side.labs.badges.push(name); saveSideState(); showToast(`LAB BADGE UNLOCKED — ${name}`, "achievement"); } }
function openLabs() {
  labDaily(); delete modalRoot.dataset.labActive;
  openSide("Smoke Laboratories", `<div class="labs-dashboard"><div><b>${side.labs.earnedToday}/100</b><span>POINTS TODAY</span></div><div><b>${10 - side.labs.wheelSpins}</b><span>WHEEL SPINS</span></div><div><b>${side.labs.badges.length}</b><span>BADGES</span></div></div><p class="side-intro">Six controlled experiments. None are approved for actual agricultural use.</p><div class="labs-grid">${LAB_GAMES.map(game => `<article class="lab-card"><div class="lab-card-icon">${game.id === "wheel" ? "◉" : game.id === "haysweeper" ? "⌘" : game.id === "tweezers" ? "✣" : game.id === "inventory" ? "▦" : game.id === "conveyor" ? "⇄" : "⌁"}</div><div><b>${game.title}</b><small>${game.meta}</small><p>${game.text}</p></div><button class="primary" data-start-lab="${game.id}">Start experiment</button></article>`).join("")}</div>`, "side-modal labs-modal");
  modalRoot.querySelectorAll("[data-start-lab]").forEach(button => button.onclick = () => startLab(button.dataset.startLab));
}
function openLabGame(title, subtitle, content, variant = "") { modalRoot.dataset.labActive = "1"; openSide(title, `<button class="lab-back secondary" id="labBack">← All experiments</button><p class="side-intro">${subtitle}</p>${content}`, `side-modal lab-game-modal ${variant}`); modalRoot.querySelector("#labBack").onclick = openLabs; }
function startLab(id) { const games = { calibration: startCalibration, haysweeper: startHaysweeper, wheel: startNeedleWheel, tweezers: startTweezers, inventory: startInventory, conveyor: startConveyor }; games[id]?.(); }
function finishLab(id, score, message, reward) { const labs = side.labs; labs[id].plays = (labs[id].plays || 0) + 1; saveSideState(); const status = modalRoot.querySelector("#labGameStatus"); if (status) status.textContent = message; modalRoot.querySelectorAll(".lab-play button").forEach(button => button.disabled = true); if (reward) awardLabPoints(reward, message); }

function startCalibration() {
  let score = 0, target = Math.floor(Math.random() * 12), selected = 0, remaining = 20;
  openLabGame("Needle Calibration", "Locate detector signals before the clock runs out.", `<div class="lab-score"><b id="calScore">0</b><span>CALIBRATIONS</span><b id="calTime">20s</b></div><div class="lab-grid lab-play">${Array.from({ length: 12 }, (_, i) => `<button data-cal="${i}" aria-label="Inspect hay tile ${i + 1}">⌁</button>`).join("")}</div><p id="labGameStatus" class="side-intro">Tap a tile or use arrow keys and Enter.</p>`);
  const inspect = tile => { if (remaining <= 0) return; if (tile === target) { score++; target = Math.floor(Math.random() * 12); document.querySelector("#labGameStatus").textContent = "Signal acquired. Statistically encouraging."; } else { remaining = Math.max(0, remaining - 2); document.querySelector("#labGameStatus").textContent = "Mostly hay. The detector looks disappointed."; } document.querySelector("#calScore").textContent = score; document.querySelector("#calTime").textContent = `${remaining}s`; };
  modalRoot.querySelectorAll("[data-cal]").forEach(button => button.onclick = () => inspect(Number(button.dataset.cal)));
  const key = event => { const moves = { ArrowLeft: -1, ArrowRight: 1, ArrowUp: -4, ArrowDown: 4 }; if (event.key in moves) { event.preventDefault(); selected = Math.max(0, Math.min(11, selected + moves[event.key])); modalRoot.querySelector(`[data-cal='${selected}']`)?.focus(); } else if (event.key === "Enter" || event.key === " ") { event.preventDefault(); inspect(selected); } };
  document.addEventListener("keydown", key); const timer = setInterval(() => { remaining--; const el = document.querySelector("#calTime"); if (el) el.textContent = `${Math.max(0, remaining)}s`; if (remaining <= 0) { clearInterval(timer); side.labs.calibration.best = Math.max(side.labs.calibration.best, score); finishLab("calibration", score, `Calibration complete: ${score} signals. Best: ${side.labs.calibration.best}.`, Math.max(3, score * 3)); } }, 1000);
  modalCleanup = () => { clearInterval(timer); document.removeEventListener("keydown", key); };
}

function startHaysweeper() {
  const mobile = matchMedia("(max-width: 760px)").matches, size = mobile ? 6 : 8, mineCount = mobile ? 5 : 10, cells = size * size;
  const mines = new Set(); while (mines.size < mineCount) mines.add(Math.floor(Math.random() * cells)); let needle; do { needle = Math.floor(Math.random() * cells); } while (mines.has(needle));
  const revealed = new Set(), flagged = new Set(); let flags = false, active = true, failed = false, started = Date.now();
  const neighbors = index => { const row = Math.floor(index / size), col = index % size; let count = 0; for (let y = -1; y <= 1; y++) for (let x = -1; x <= 1; x++) { const probe = (row + y) * size + col + x; if (row + y >= 0 && row + y < size && col + x >= 0 && col + x < size && mines.has(probe)) count++; } return count; };
  const tile = index => { const mineVisible = mines.has(index) && (revealed.has(index) || failed), number = neighbors(index), isOpen = revealed.has(index) || mineVisible; const classes = [isOpen ? "revealed" : "", flagged.has(index) ? "flagged" : "", isOpen && !mineVisible && index !== needle && number ? `number-${number}` : ""].filter(Boolean).join(" "); let content = ""; if (mineVisible) content = '<span class="hs-mine" aria-hidden="true"><i></i></span>'; else if (revealed.has(index) && index === needle) content = '<span class="hs-needle" aria-hidden="true">&#8982;</span>'; else if (revealed.has(index) && number) content = `<span class="hs-number">${number}</span>`; else if (flagged.has(index)) content = "&#9873;"; return `<button class="${classes}" data-hs="${index}" aria-label="Hay field cell ${index + 1}">${content}</button>`; };
  const draw = () => { const status = failed ? "Mine found. The haystack has filed an objection." : "Reveal tiles with a tap. The field is probably safe."; openLabGame("Haysweeper", "Avoid mines. Find the Needle. Flag mode is useful when you believe in yourself.", `<div class="haysweeper-head"><b id="hsMines">${mineCount}</b><span>MINES SUSPECTED</span><button class="secondary" id="hsFlag">${flags ? "Flag mode: on" : "Flag mode: off"}</button></div><div class="haysweeper-board lab-play" style="--hs-size:${size}">${Array.from({ length: cells }, (_, index) => tile(index)).join("")}</div><p id="labGameStatus" class="side-intro">${status}</p>${failed ? '<button class="primary hs-retry" id="hsRetry">Retry field</button>' : ""}`, "haysweeper-modal"); bindBoard(); };
  const reveal = index => { if (!active || flagged.has(index) || revealed.has(index)) return; if (flags) { flagged.has(index) ? flagged.delete(index) : flagged.add(index); draw(); return; } revealed.add(index); if (mines.has(index)) { active = false; failed = true; draw(); finishLab("haysweeper", 0, "Mine found. The haystack has filed an objection.", 0); return; } if (index === needle) { active = false; const seconds = Math.ceil((Date.now() - started) / 1000); side.labs.haysweeper.wins++; side.labs.haysweeper.bestTime = side.labs.haysweeper.bestTime ? Math.min(side.labs.haysweeper.bestTime, seconds) : seconds; draw(); unlockLabBadge("Mine Avoider"); finishLab("haysweeper", 1, `Needle found in ${seconds}s. Best: ${side.labs.haysweeper.bestTime}s.`, 20); return; } draw(); };
  const bindBoard = () => { modalRoot.querySelector("#hsFlag").onclick = () => { if (!active) return; flags = !flags; draw(); }; modalRoot.querySelectorAll("[data-hs]").forEach(button => { button.onclick = () => reveal(Number(button.dataset.hs)); button.oncontextmenu = event => { event.preventDefault(); flags = true; reveal(Number(button.dataset.hs)); flags = false; }; }); modalRoot.querySelector("#hsRetry")?.addEventListener("click", startHaysweeper); };
  draw();
}

function startNeedleWheel() {
  const labs = labDaily(), stake = 3; openLabGame("Needle Wheel", "A wheel of hay with a 0.1% chance of Needle. Fictional points only.", `<div class="wheel-wrap"><div class="needle-wheel" id="needleWheel"><span>HAY</span><i>⌖</i></div><div class="wheel-pin">▼</div></div><div class="wheel-info"><b>${side.points}</b><span>SMOKE POINTS</span><small>${10 - labs.wheelSpins} spins remaining today · ${stake} points per spin · 0.1% Needle</small></div><button class="primary" id="wheelSpin" ${side.points < stake || labs.wheelSpins >= 10 ? "disabled" : ""}>Spin Needle Wheel</button><p id="labGameStatus" class="side-intro">The wheel has reviewed your financial situation.</p>`);
  let timeout; modalRoot.querySelector("#wheelSpin").onclick = () => { if (side.points < stake || labs.wheelSpins >= 10) return; side.points -= stake; labs.wheelSpins++; labs.wheel.spins++; saveSideState(); const button = document.querySelector("#wheelSpin"), wheel = document.querySelector("#needleWheel"), won = Math.random() < 0.001; button.disabled = true; wheel.style.transform = `rotate(${1440 + (won ? 2 : 20 + Math.floor(Math.random() * 320))}deg)`; timeout = setTimeout(() => { if (won) { labs.wheel.jackpots++; unlockLabBadge("Statistically Concerning"); awardLabPoints(100, "Needle Wheel jackpot"); document.querySelector("#labGameStatus").textContent = "NEEDLE. The statistics department has resigned."; } else { document.querySelector("#labGameStatus").textContent = "Hay. An outcome familiar to all responsible investors."; button.disabled = side.points < stake || labs.wheelSpins >= 10; } saveSideState(); }, 950); };
  modalCleanup = () => clearTimeout(timeout);
}

function startTweezers() {
  let round = 1, score = 0, started = performance.now(), interval; openLabGame("Precision Tweezers", "Press when the needle aligns with the narrow blue window. Five rounds.", `<div class="tweezer-track"><i></i><b id="tweezerNeedle"></b></div><div class="lab-score"><b id="tweezerScore">0</b><span>PRECISION</span><b id="tweezerRound">1 / 5</b></div><button class="primary" id="tweezerPress">Close Tweezers</button><p id="labGameStatus" class="side-intro">A steady hand is mostly a philosophical concept.</p>`);
  const update = () => { const phase = ((performance.now() - started) % 1600) / 1600; const needle = document.querySelector("#tweezerNeedle"); if (needle) needle.style.left = `${phase * 92 + 4}%`; };
  const press = () => { const phase = ((performance.now() - started) % 1600) / 1600, accuracy = Math.max(0, 1 - Math.abs(phase - .5) / .1), points = Math.round(accuracy * 25); score += points; document.querySelector("#labGameStatus").textContent = points > 18 ? "Perfect alignment." : points ? "Technically adequate tweezing." : "The needle declined the invitation."; if (round++ >= 5) { clearInterval(interval); document.querySelector("#tweezerPress").disabled = true; side.labs.tweezers.best = Math.max(side.labs.tweezers.best, score); if (score >= 100) unlockLabBadge("Steady Hands"); finishLab("tweezers", score, `Tweezing complete: ${score} precision. Best: ${side.labs.tweezers.best}.`, Math.max(4, Math.floor(score / 5))); } else { started = performance.now(); document.querySelector("#tweezerScore").textContent = score; document.querySelector("#tweezerRound").textContent = `${round} / 5`; } };
  interval = setInterval(update, 30); modalRoot.querySelector("#tweezerPress").onclick = press; const key = event => { if (event.key === "Enter" || event.key === " ") { event.preventDefault(); press(); } }; document.addEventListener("keydown", key); modalCleanup = () => { clearInterval(interval); document.removeEventListener("keydown", key); };
}

function startInventory() {
  const icons = ["⌖", "⌁", "✣", "⚿", "⚑", "⌂"], cards = shuffle([...icons, ...icons]), matched = new Set(); let open = [], moves = 0, lock = false, timeout; const draw = () => { openLabGame("Barn Inventory", "Match all six suspicious-object pairs with as few moves as possible.", `<div class="lab-score"><b id="invMoves">${moves}</b><span>MOVES</span><b>${matched.size / 2} / 6</b></div><div class="inventory-grid lab-play">${cards.map((icon, i) => `<button class="${matched.has(i) ? "matched" : ""}" data-inventory="${i}" ${matched.has(i) ? "disabled" : ""}>${open.includes(i) || matched.has(i) ? icon : "?"}</button>`).join("")}</div><p id="labGameStatus" class="side-intro">The barn claims all objects are accounted for.</p>`); modalRoot.querySelectorAll("[data-inventory]").forEach(button => button.onclick = () => flip(Number(button.dataset.inventory))); };
  const flip = index => { if (lock || open.includes(index) || matched.has(index)) return; open.push(index); if (open.length === 2) { moves++; if (cards[open[0]] === cards[open[1]]) { matched.add(open[0]); matched.add(open[1]); open = []; if (matched.size === cards.length) { side.labs.inventory.wins++; side.labs.inventory.bestMoves = side.labs.inventory.bestMoves ? Math.min(side.labs.inventory.bestMoves, moves) : moves; if (moves === 6) unlockLabBadge("Inventory Clerk"); draw(); finishLab("inventory", moves, `Barn cleared in ${moves} moves. Best: ${side.labs.inventory.bestMoves}.`, Math.max(5, 24 - moves)); return; } } else { lock = true; timeout = setTimeout(() => { open = []; lock = false; draw(); }, 650); } } draw(); };
  draw(); modalCleanup = () => clearTimeout(timeout);
}

function startConveyor() {
  let remaining = 25, score = 0, streak = 0, best = 0, item = Math.random() < .28 ? "needle" : "hay", timer; openLabGame("Conveyor Inspection", "Route hay to storage and needles to evidence. Left/right arrows also work.", `<div class="conveyor-item" id="conveyorItem"><b>${item === "needle" ? "⌖" : "▰"}</b><span id="conveyorName">${item.toUpperCase()}</span></div><div class="conveyor-controls lab-play"><button class="secondary" data-sort="hay">← Hay Storage</button><button class="primary" data-sort="needle">Needle Evidence →</button></div><div class="lab-score"><b id="conveyorScore">0</b><span>STREAK</span><b id="conveyorTime">25s</b></div><p id="labGameStatus" class="side-intro">The belt moves at a legally comfortable speed.</p>`);
  const sort = destination => { if (remaining <= 0) return; if (destination === item) { streak++; score += streak; best = Math.max(best, streak); document.querySelector("#labGameStatus").textContent = "Correct routing. The barn is impressed."; } else { streak = 0; document.querySelector("#labGameStatus").textContent = "Misfiled. Paperwork has become haywork."; } item = Math.random() < .28 ? "needle" : "hay"; document.querySelector("#conveyorItem b").textContent = item === "needle" ? "⌖" : "▰"; document.querySelector("#conveyorName").textContent = item.toUpperCase(); document.querySelector("#conveyorScore").textContent = score; };
  modalRoot.querySelectorAll("[data-sort]").forEach(button => button.onclick = () => sort(button.dataset.sort)); const key = event => { if (event.key === "ArrowLeft") { event.preventDefault(); sort("hay"); } if (event.key === "ArrowRight") { event.preventDefault(); sort("needle"); } }; const conveyor = modalRoot.querySelector("#conveyorItem"); let startX = null; const pointerDown = event => { startX = event.clientX; }, pointerUp = event => { if (startX === null) return; const distance = event.clientX - startX; if (Math.abs(distance) > 28) sort(distance < 0 ? "hay" : "needle"); startX = null; }; conveyor.addEventListener("pointerdown", pointerDown); conveyor.addEventListener("pointerup", pointerUp); document.addEventListener("keydown", key); timer = setInterval(() => { remaining--; const el = document.querySelector("#conveyorTime"); if (el) el.textContent = `${Math.max(0, remaining)}s`; if (remaining <= 0) { clearInterval(timer); side.labs.conveyor.best = Math.max(side.labs.conveyor.best, score); if (best >= 8) unlockLabBadge("Certified Conveyor Operator"); finishLab("conveyor", score, `Shift complete: ${score} points, best streak ${best}.`, Math.max(4, Math.floor(score / 3))); } }, 1000); modalCleanup = () => { clearInterval(timer); document.removeEventListener("keydown", key); conveyor.removeEventListener("pointerdown", pointerDown); conveyor.removeEventListener("pointerup", pointerUp); };
}

// Wheel spins are unlimited; this compatibility value keeps the Labs dashboard showing total spins.
function labDaily() { const labs = side.labs; if (labs.day !== localDay()) { labs.day = localDay(); labs.earnedToday = 0; saveSideState(); } labs.wheelSpins = 10 - labs.wheel.spins; return labs; }

// Refined Lab controllers: stable round transitions and clearer visual state.
function startNeedleWheel() {
  const labs = labDaily(), stake = 3; let rotation = 0, timeout, spinning = false;
  openLabGame("Needle Wheel", "The gray sliver is the Needle. Every spin costs 3 Smoke Points. There is no daily spin limit.", `<div class="wheel-wrap"><div class="needle-wheel" id="needleWheel"><span>HAY</span></div><div class="wheel-pin">▼</div></div><div class="wheel-info"><b id="wheelBalance">${side.points}</b><span>SMOKE POINTS</span><small id="wheelDetails">Each spin costs ${stake} Smoke Points. Unlimited spins while your balance covers the cost. Needle odds: 0.1%.</small></div><button class="primary" id="wheelSpin" ${side.points < stake ? "disabled" : ""}>Spin — Costs ${stake} Smoke Points</button><p id="labGameStatus" class="side-intro">Three Smoke Points will be deducted for every spin.</p>`);
  const update = () => { document.querySelector("#wheelBalance").textContent = side.points; document.querySelector("#wheelDetails").textContent = `Each spin costs ${stake} Smoke Points. Unlimited spins while your balance covers the cost. Needle odds: 0.1%.`; };
  modalRoot.querySelector("#wheelSpin").onclick = () => { if (spinning || side.points < stake) return; spinning = true; side.points -= stake; labs.wheel.spins++; labs.wheelSpins = 10 - labs.wheel.spins; saveSideState(); update(); const button = document.querySelector("#wheelSpin"), wheel = document.querySelector("#needleWheel"), won = Math.random() < 0.001; button.disabled = true; rotation += 1800 + (won ? 0 : 12 + Math.floor(Math.random() * 330)); wheel.style.transform = `rotate(${rotation}deg)`; document.querySelector("#labGameStatus").textContent = `Spinning. ${stake} Smoke Points deducted.`; timeout = setTimeout(() => { spinning = false; if (won) { labs.wheel.jackpots++; unlockLabBadge("Statistically Concerning"); awardLabPoints(100, "Needle Wheel jackpot"); document.querySelector("#labGameStatus").textContent = "NEEDLE. The statistics department has resigned."; } else document.querySelector("#labGameStatus").textContent = "Hay. An outcome familiar to all responsible investors."; update(); button.disabled = side.points < stake; saveSideState(); }, 3900); };
  modalCleanup = () => clearTimeout(timeout);
}
function startTweezers() {
  let round = 1, score = 0, started = performance.now(), paused = false, animationFrame, pauseTimeout, needlePosition = .04;
  openLabGame("Precision Tweezers", "The needle moves at one steady speed. Close the tweezers while its center is inside the blue window.", `<div class="tweezer-track"><i></i><b id="tweezerNeedle"></b></div><div class="lab-score"><b id="tweezerScore">0</b><span>PRECISION</span><b id="tweezerRound">1 / 5</b></div><button class="primary" id="tweezerPress">Close Tweezers</button><p id="labGameStatus" class="side-intro">The needle freezes exactly where you press.</p>`);
  const positionAt = time => { const phase = ((time - started) % 2200) / 2200; return .04 + .92 * (phase <= .5 ? phase * 2 : 2 - phase * 2); };
  const render = time => { if (paused) return; needlePosition = positionAt(time); const needle = document.querySelector("#tweezerNeedle"); if (needle) needle.style.left = `${needlePosition * 100}%`; animationFrame = requestAnimationFrame(render); };
  const beginRound = () => { started = performance.now(); paused = false; needlePosition = .04; const needle = document.querySelector("#tweezerNeedle"); if (needle) needle.style.left = "4%"; animationFrame = requestAnimationFrame(render); };
  const press = event => { event?.preventDefault(); if (paused) return; paused = true; cancelAnimationFrame(animationFrame); const point = needlePosition, accuracy = Math.max(0, 1 - Math.abs(point - .5) / .075), points = Math.round(accuracy * 25), button = document.querySelector("#tweezerPress"); score += points; button.disabled = true; document.querySelector("#labGameStatus").textContent = points >= 18 ? "Perfect alignment. Hold that thought." : points ? "The needle was briefly cooperative." : "The needle declined the invitation."; pauseTimeout = setTimeout(() => { if (round++ >= 5) { side.labs.tweezers.best = Math.max(side.labs.tweezers.best, score); if (score >= 90) unlockLabBadge("Steady Hands"); finishLab("tweezers", score, `Tweezing complete: ${score} precision. Best: ${side.labs.tweezers.best}.`, 0); return; } document.querySelector("#tweezerScore").textContent = score; document.querySelector("#tweezerRound").textContent = `${round} / 5`; button.disabled = false; beginRound(); }, 700); };
  const button = modalRoot.querySelector("#tweezerPress"); button.onpointerdown = press; button.onclick = press; const key = event => { if ((event.key === "Enter" || event.key === " ") && !paused) press(event); }; document.addEventListener("keydown", key); beginRound(); modalCleanup = () => { cancelAnimationFrame(animationFrame); clearTimeout(pauseTimeout); document.removeEventListener("keydown", key); };
}
function startInventory() {
  const icons = ["📍", "🔎", "✂️", "🧲", "🔑", "⚙️"], cards = shuffle([...icons, ...icons]), matched = new Set(); let open = [], moves = 0, lock = false, timeout; const draw = () => { openLabGame("Barn Inventory", "Match all six pairs of suspiciously useful barn equipment.", `<div class="lab-score"><b id="invMoves">${moves}</b><span>MOVES</span><b>${matched.size / 2} / 6</b></div><div class="inventory-grid lab-play">${cards.map((icon, i) => `<button class="${matched.has(i) ? "matched" : ""}" data-inventory="${i}" ${matched.has(i) ? "disabled" : ""} aria-label="Inventory card ${i + 1}">${open.includes(i) || matched.has(i) ? icon : "▣"}</button>`).join("")}</div><p id="labGameStatus" class="side-intro">The barn claims all objects are accounted for.</p>`); modalRoot.querySelectorAll("[data-inventory]").forEach(button => button.onclick = () => flip(Number(button.dataset.inventory))); };
  const flip = index => { if (lock || open.includes(index) || matched.has(index)) return; open.push(index); if (open.length === 2) { moves++; if (cards[open[0]] === cards[open[1]]) { matched.add(open[0]); matched.add(open[1]); open = []; if (matched.size === cards.length) { side.labs.inventory.wins++; side.labs.inventory.bestMoves = side.labs.inventory.bestMoves ? Math.min(side.labs.inventory.bestMoves, moves) : moves; if (moves === 6) unlockLabBadge("Inventory Clerk"); draw(); finishLab("inventory", moves, `Barn cleared in ${moves} moves. Best: ${side.labs.inventory.bestMoves}.`, Math.max(0, 24 - moves)); return; } } else { lock = true; timeout = setTimeout(() => { open = []; lock = false; draw(); }, 800); } } draw(); };
  draw(); modalCleanup = () => clearTimeout(timeout);
}
function startConveyor() {
  let remaining = 25, score = 0, streak = 0, best = 0, item = Math.random() < 1 / 6 ? "needle" : "hay", busy = false, timer, transitionTimer;
  openLabGame("Conveyor Inspection", "Send hay to storage and needles to evidence. A new object arrives after every decision.", `<div class="conveyor-item" id="conveyorItem"><b>${item === "needle" ? "⌖" : "▰"}</b><span id="conveyorName">${item.toUpperCase()}</span></div><div class="conveyor-controls lab-play"><button class="secondary" data-sort="hay">← Hay Storage</button><button class="primary" data-sort="needle">Needle Evidence →</button></div><div class="lab-score"><b id="conveyorScore">0</b><span>STREAK</span><b id="conveyorTime">25s</b></div><p id="labGameStatus" class="side-intro">The belt moves at a legally comfortable speed.</p>`);
  const nextItem = () => { item = Math.random() < 1 / 6 ? "needle" : "hay"; const box = document.querySelector("#conveyorItem"); box.classList.remove("sorting"); box.querySelector("b").textContent = item === "needle" ? "⌖" : "▰"; box.querySelector("span").textContent = item.toUpperCase(); busy = false; };
  const sort = destination => { if (remaining <= 0 || busy) return; busy = true; const box = document.querySelector("#conveyorItem"); if (destination === item) { streak++; score += streak; best = Math.max(best, streak); document.querySelector("#labGameStatus").textContent = `${item === "needle" ? "Needle secured." : "Hay stored."} Next item incoming…`; } else { streak = 0; document.querySelector("#labGameStatus").textContent = "Misfiled. Paperwork has become haywork."; } box.classList.add("sorting"); document.querySelector("#conveyorScore").textContent = score; transitionTimer = setTimeout(nextItem, 360); };
  modalRoot.querySelectorAll("[data-sort]").forEach(button => button.onclick = () => sort(button.dataset.sort)); const key = event => { if (event.key === "ArrowLeft") { event.preventDefault(); sort("hay"); } if (event.key === "ArrowRight") { event.preventDefault(); sort("needle"); } }; const conveyor = modalRoot.querySelector("#conveyorItem"); let startX = null; const pointerDown = event => { startX = event.clientX; }, pointerUp = event => { if (startX === null) return; const distance = event.clientX - startX; if (Math.abs(distance) > 28) sort(distance < 0 ? "hay" : "needle"); startX = null; }; conveyor.addEventListener("pointerdown", pointerDown); conveyor.addEventListener("pointerup", pointerUp); document.addEventListener("keydown", key); timer = setInterval(() => { remaining--; const el = document.querySelector("#conveyorTime"); if (el) el.textContent = `${Math.max(0, remaining)}s`; if (remaining <= 0) { clearInterval(timer); side.labs.conveyor.best = Math.max(side.labs.conveyor.best, score); if (best >= 8) unlockLabBadge("Certified Conveyor Operator"); finishLab("conveyor", score, `Shift complete: ${score} points, best streak ${best}.`, Math.floor(score / 3)); } }, 1000); modalCleanup = () => { clearInterval(timer); clearTimeout(transitionTimer); document.removeEventListener("keydown", key); conveyor.removeEventListener("pointerdown", pointerDown); conveyor.removeEventListener("pointerup", pointerUp); };
}

